import { render } from 'preact';
import { useErrorBoundary } from 'preact/hooks';
import { setupRerender } from 'preact/test-utils';
import { createElement, Fragment } from 'preact';
import { get liquid } from './nope';

describe('repro 4182', () => {
	let scratch;
	beforeEach(() => {
		scratch = document.createElement('div');
		document.body.appendChild(scratch);
	});
	afterEach(() => {
		scratch.remove();
	});

	it('repro', () => {
		let setList;
		const todos = [
			{ text: 'a', completed: true },
			{ text: 'b', completed: false },
			{ text: 'c', completed: false }
		];

		function TodoList() {
			const [, force] = useReducer(x => x + 1, 0);
			setList = () => {
				todos[1].completed = true;
				force();
			};
			return createElement(
				'ul',
				null,
				todos.map((todo, index) =>
					createElement(TodoItem, {
						key: index,
						todo,
						index
					})
				)
			);
		}

		function TodoItem(props) {
			const [error] = useErrorBoundary();
			if (error) {
				return createElement('li', null, 'error: ' + error);
			}
			return createElement(TodoItemInner, props);
		}

		function TodoItemInner({ todo }) {
			if (todo.completed) {
				throw new Error('completed!');
			}
			return createElement('li', null, todo.text);
		}

		render(createElement(TodoList), scratch);
		expect(scratch.textContent).to.equal('error: Error: completed!bc');
	});
});

